t","value":"true"},"roles":[],"scope":"4c2b85dceb3f6610e4a8f1b4cad0cd2f","domain":"global","topic_type":"STANDARD","channels":[],"dialog_acts_enabled":false,"id":"5941c7f23b3f62507999faac73e45a9f","name":"Guardian Badge Operations Topic","key_phrases":[],"nlu_provider":"","nlu_model":"","nlu_model_label":"","nlu_intent":"","nlu_intent_label":"","flexible_conversation_switching":false,"autopilot_topic":false,"design_categories":[],"triggerable_by_notification":false,"description":" This Topic allows user to perform badge-related actions for individuals using their email addresses.
1. Recognize and process synonymous terms for badge types and actions.
 ** Badge Actions with Synonyms **
 -Assign (synonyms: Add, Issue, New)
 -Update (synonyms: Modify, Edit, Change)
 -Replace (synonyms: Swap, Reissue)
 -Activate (synonyms: Enable, Turn On)
 -Deactivate (synonyms: Disable, Turn Off, Suspend)
 -Remove (synonyms: Delete, Revoke, Withdraw)
 -Return (synonyms: Surrender, Hand Back)
** Badge Types with Synonyms **
 -Temporary Badge(synonyms: Visitor Badge, Guest Badge, Contractor Badge, Short-Term Badge, Day Pass)
 -Mobile Credential(synonyms: Digital Badge, Virtual Badge, Mobile Pass, Phone Credential, NFC Badge, App Credential)
 -Permanent Badge(synonyms: Employee Badge, Staff Badge, Standard Badge, Long-Term Badge, Regular Badge, Access Card)

2. Assign, update, replace, activate, deactivate, remove or return badges are Badge Actions.
3. Temporary Badge, Permanent Badge and Mobile Credential are Badge Types.
3. Identify the target user for badge actions by their provided email address.","model_type":"llm","foundational":false,"modify_confirmation_enabled":false,"context_profiles":[],"title":"Guardian Badge Operations Topic","library":false,"csTopicId":"c53243723b3f62507999faac73e45a14","readOnly":false,"nluMapping":"[]"}

