          "name": "Identify the user Intent",
          "script": "(function execute() {\n    if(null != vaInputs.topic_input_user_email && \"\" != vaInputs.topic_input_user_email){\n        vaVars.user_email = vaInputs.topic_input_user_email.toString().toLowerCase();\n    }else{\n\t\tvaVars.user_email = \"\"; \n    }\n    \n    if(null != vaInputs.topic_input_badge_action && \"\" != vaInputs.topic_input_badge_action){\n        vaVars.badge_action = vaInputs.topic_input_badge_action.toString().toLowerCase();\n    }else{\n\t    vaVars.badge_action = \"\";\n    }\n\n    if(null != vaInputs.topic_input_badge_type && \"\" != vaInputs.topic_input_badge_type){\n        vaVars.badge_type = vaInputs.topic_input_badge_type.toString().toLowerCase();\n    }else{\n\t\tvaVars.badge_type = \"\"; \n    }\n})()\n",
          "stepType": "ScriptAction",
          "applicability": {
            "value": "",
            "mode": "query"
          }
        },
